import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = 3
    let k = if a > 1 { 10 } else { 20 }
    if k == 10 { io.println("if-ok") } else { io.println("if-bad") }
    let j = if a > 5 { 1 } else if a > 2 { 2 } else { 3 }
    if j == 2 { io.println("chain-ok") } else { io.println("chain-bad") }
    let b = {
        let t = a + 1
        t * 2
    }
    if b == 8 { io.println("blk-ok") } else { io.println("blk-bad") }
    let _ = if a > 1 { io.println("unit1") } else { io.println("unit2") }
    let r = scope timeout(1000) { 5 }
    let n = match r {
        Ok(x) => x
        Err(_) => 0 - 1
    }
    if n == 5 { io.println("match-ok") } else { io.println("match-bad") }
    return Ok(())
}
